  ('aus-wem-a-gulasch-mochn', 'aus wem a Gulasch mochn', '', '', '', '', 'aus jemandem ein Gulasch machen', '[{"kategorie": "", "text": "jemanden zerpflücken, durch den Fleischwolf drehen"}, {"kategorie": "", "text": "jemanden in die Mangel nehmen, heftig bedrängen"}, {"kategorie": "", "text": "jemandem arg zusetzen, jemandem so richtig einheizen"}, {"kategorie": "", "text": "jemandem ans Leder gehen, mit jemandem Schlitten fahren"}, {"kategorie": "", "text": "[[wem katolisch mochn]]"}]'::jsonb, ''),
  ('aufgwaamd-is-nua-a-gulasch-guad', 'aufgwaamd is nua a Gulasch guad!', '', '', '', '', 'Aufgewärmt ist nur ein Gulasch gut!', '[{"kategorie": "", "text": "Vergangenes bleibt besser vergangen!  2. Was gewesen ist, ist gewesen!"}]'::jsonb, ''),
  ('auf-jedn-foi-scheissn-hund-kane-gummiboin', 'Auf jedn Foi scheissn Hund kane Gummiboin!', '', '', '', '', 'Auf jeden Fall scheißen Hunde keine Gummibälle!', '[{"kategorie": "", "text": "Sei es, wie es sei!  2. Man muss das Schicksal nehmen, wie es kommt!"}]'::jsonb, ''),
  ('waunn-des-kneedl-hupfd-haumma-a-eadbeebm', 'Waunn des Kneedl hupfd, haumma a Eadbeebm!', '', '', '', '', 'Wenn das Knödel hüpft, haben wir ein Erdbeben!', '[{"kategorie": "wörtlich", "text": "\"Wenn die Dickmadam hüpft, haben wir ein Erdbeben!\"  2. Wenn die Wuchtbrumme springt, wackelt der Boden!  3. Wenn das Schwergewicht tanzt, vibriert die Welt!"}]'::jsonb, ''),
