  ('pedaschduafa-haad', 'Pedaschduafa Haad', '', '', '', '', 'Petersdorfer Heide', '[{"kategorie": "wörtlich", "text": "\"Perchtoldsdorfer Heide\""}, {"kategorie": "", "text": "eines der beliebtesten Naherholgsgebiete der Wiener nahe [[Perchtoldsdorf]] (an der südlichen Stadtgrenze von Wien) und Teil des Naturparks \"Föhrenberge\" mit zahlreichen Wiesen, Heideflächen, Wäldern, Wander- und Spazierwegen (berühmt für seine \"Zieselkolonie\") ."}]'::jsonb, ''),
  ('voikspark-laabeag', 'Voikspark Laabeag', '', '', '', '', 'Volkspark Laaerberg', '[{"kategorie": "", "text": "romantischer Wiener Erholungspark im 10. Wiener Gemeindebezirk ([[Favoriten]])"}, {"kategorie": "", "text": "Erholungs- und Freizeitpark am Südhang des [[Laaerbergs]], welcher neben dem Laaerwald und dem [[Kurpark]] Oberlaa auch den legendären [[Böhmischen]] Prater umfasst"}]'::jsonb, ''),
  ('viktoa-adla-moakt', 'Viktoa-Adla-Moakt', '', '', '', '', 'Viktor-Adler-Markt', '[{"kategorie": "allg.", "text": "\"einer der bekanntesten und lebendigsten Märkte in Wien\""}, {"kategorie": "", "text": "Er befindet sich im 10. Wiener Gemeindebezirk ([[Favoriten]]) an der [[Favoritner]] Fußgängerzone und ist nach dem österreichischen Politiker und Begründer der österreichischen Sozialdemokratie, Viktor Adler, benannt"}, {"kategorie": "", "text": "Der Viktor-Adler-Markt wurde Ende des 19. Jahrhunderts gegründet und entwickelte sich schnell zu einem wichtigen Handelsplatz im damals schnell wachsenden Bezirk Favoriten."}]'::jsonb, ''),
  ('therme-wiin', 'Therme Wiin', '', '', '', '', 'Therme Wien', '[{"kategorie": "allg.", "text": "eines der größten und modernsten Thermalbäder Europas, das im 10. Wiener Gemeindebezirk ([[Favoriten]]), im Stadtteil Oberlaa, liegt"}, {"kategorie": "", "text": "Die Therme Wien wurde im Jahr 2010 eröffnet und ersetzt das alte Thermalbad Oberlaa, das seit den 1970er Jahren bestand. Das moderne Thermalzentrum wurde auf den Heilquellen des [[Laaerbergs]] errichtet, die bereits seit Jahrhunderten für ihre heilende Wirkung bekannt sind"}, {"kategorie": "", "text": "Die Therme Wien verfügt über eine Vielzahl von Innen- und Außenbecken, die mit mineralhaltigem Thermalwasser aus den Tiefen des Laaerbergs gespeist werden. Diese Becken bieten verschiedene Wassertemperaturen und Hydromassage-Möglichkeiten, die zur Entspannung und Regeneration beitragen"}, {"kategorie": "", "text": "Die Therme ist von großzügigen Parkanlagen umgeben, darunter der [[Kurpark]] Oberlaa, der eine zusätzliche Erholungsfläche bietet und Spaziergänge sowie Outdoor-Aktivitäten ermöglicht."}]'::jsonb, ''),
  ('kuapark-obalaa', 'Kuapark Obalaa', '', '', '', '', 'Kurpark Oberlaa', '[{"kategorie": "allg.", "text": "weitläufige und idyllische Parkanlage im 10. Wiener Gemeindebezirk ([[Favoriten]])"}, {"kategorie": "", "text": "Der Kurpark Oberlaa wurde im Rahmen der Wiener Internationalen Gartenschau (WIG 74) angelegt, die 1974 stattfand. Die Gartenschau sollte internationale Gartenkunst präsentieren und die Stadt Wien um eine große, öffentliche Grünfläche bereichern. Nach Abschluss der Gartenschau blieb der Park erhalten und wurde in den folgenden Jahrzehnten zu einem beliebten Naherholungsgebiet ausgebaut"}, {"kategorie": "", "text": "Er grenzt an die [[Therme]] Wien erstreckt sich über ein großes Areal, das von Wohngebieten und landwirtschaftlichen Flächen umgeben ist"}, {"kategorie": "", "text": "Der Kurpark Oberlaa ist in verschiedene Themengärten und Landschaftsbereiche unterteilt, die jeweils unterschiedliche Stile und Pflanzenarten präsentieren. Zu den bekanntesten Bereichen gehören der Japanische Garten, der Rosenhügel, der Liebesgarten, der Filmstadtplatz und der Allergiegarten."}]'::jsonb, ''),
  ('si-wos-ind-hoa-schmiian-kennan', 'si wos ind Hoa schmiian kennan', '', '', '', '', 'sich etwas in die Haare schmieren können', '[{"kategorie": "", "text": "sich etwas an den Hut stecken können"}, {"kategorie": "", "text": "sich etwas abschminken können"}, {"kategorie": "", "text": "sich etwas [[aufs]] Hirn picken können"}]'::jsonb, ''),
