  ('i-hobs-min-fotografian', 'I hobs min Fotografian!', '', '', '', '', 'Ich habe es mit dem Fotografieren!', '[{"kategorie": "wörtlich", "text": "\"Fotografieren ist mein Ding!\"  2. (allg.) \"Mein liebstes Hobby ist Fotografieren\""}, {"kategorie": "", "text": "\"Ich bin mit Leib und Seele Fotograf\""}, {"kategorie": "", "text": "\"Meine Leidenschaft ist Fotografieren!\""}]'::jsonb, ''),
