  ('ea-steigd-um-wia-da-hau-aum-mist', 'Ea steigd um wia da Hau aum Mist!', '', '', '', '', 'Er steigt um wie der Hahn am Mist!', '[{"kategorie": "", "text": "Er paradiert herum wie ein stolzer Gockel!  2. Er ist so eingebildet wie eine Primadonna!"}]'::jsonb, ''),
